CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, language TEXT NOT NULL DEFAULT 'English', learning_path TEXT, mode TEXT, onboarding_complete INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS catalogue (id INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT NOT NULL, title TEXT NOT NULL UNIQUE, description TEXT NOT NULL, tags TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS pods (id TEXT PRIMARY KEY, mode TEXT NOT NULL, language TEXT NOT NULL, learning_path TEXT, pod_type TEXT NOT NULL DEFAULT 'study', capacity INTEGER NOT NULL DEFAULT 6 CHECK((pod_type = 'study' AND capacity = 6) OR (pod_type = 'one_to_one' AND capacity = 2) OR (pod_type = 'commons' AND capacity > 0)), invitation_code TEXT UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pod_members (pod_id TEXT NOT NULL REFERENCES pods(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, joined_at TEXT NOT NULL, PRIMARY KEY(pod_id, user_id));
CREATE TABLE IF NOT EXISTS room_messages (id TEXT PRIMARY KEY, pod_id TEXT NOT NULL REFERENCES pods(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, text TEXT NOT NULL, reply_to TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS direct_messages (id TEXT PRIMARY KEY, pod_id TEXT NOT NULL REFERENCES pods(id) ON DELETE CASCADE, from_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, to_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, text TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS message_reactions (message_id TEXT NOT NULL REFERENCES room_messages(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, emoji TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(message_id, user_id, emoji));
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, metadata TEXT, completed INTEGER NOT NULL DEFAULT 0, due_date TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS focus_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, started_at TEXT NOT NULL, ended_at TEXT, kind TEXT NOT NULL CHECK(kind IN ('focus','break')), break_category TEXT CHECK(break_category IS NULL OR break_category IN ('short','long','breakfast','lunch','dinner','snack','rest','custom')), minutes INTEGER NOT NULL DEFAULT 0 CHECK(typeof(minutes) = 'integer' AND minutes >= 0));
CREATE TABLE IF NOT EXISTS friendships (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, friend_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN ('pending','accepted','blocked')), created_at TEXT NOT NULL, PRIMARY KEY(user_id, friend_id));
CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY, from_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, to_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, pod_id TEXT REFERENCES pods(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined')), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_catalogue_type ON catalogue(type);
CREATE INDEX IF NOT EXISTS idx_tasks_user ON tasks(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON focus_sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_room_messages_pod ON room_messages(pod_id, created_at);
CREATE INDEX IF NOT EXISTS idx_direct_messages_pair ON direct_messages(pod_id, from_user_id, to_user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_message_reactions_message ON message_reactions(message_id, emoji);
